import React, { useState, useEffect } from 'react';
import axios from 'axios';
import './RequestStatusDashboard.css';

// Define the structure of a request object from the backend
interface Request {
    RequestID: number;
    PatientName: string;
    Urgency: 'Emergency' | 'Urgent' | 'Scheduled';
    Status: string;
    CreatedAt: string;
}

const API_URL = 'http://localhost:3001';

const RequestStatusDashboard = () => {
    const [requests, setRequests] = useState<Request[]>([]);
    const [error, setError] = useState<string | null>(null);
    const [isLoading, setIsLoading] = useState(true);

    const fetchRequests = async () => {
        setIsLoading(true);
        setError(null);
        try {
            // In a real app, we would filter by hospitalId based on logged-in user
            const response = await axios.get(`${API_URL}/requests`);
            setRequests(response.data);
        } catch (err) {
            setError('Failed to fetch requests. Is the backend server running?');
            console.error(err);
        } finally {
            setIsLoading(false);
        }
    };

    useEffect(() => {
        fetchRequests();
        // Refresh the dashboard every 30 seconds to get live updates
        const interval = setInterval(fetchRequests, 30000);
        return () => clearInterval(interval); // Cleanup on component unmount
    }, []);

    if (isLoading) {
        return <div>Loading requests...</div>;
    }

    if (error) {
        return <div className="alert error">{error}</div>;
    }

    return (
        <div className="dashboard-container">
            <button onClick={fetchRequests} className="refresh-btn">Refresh Now</button>
            {requests.length === 0 ? (
                <p>No active requests found.</p>
            ) : (
                <table className="requests-table">
                    <thead>
                        <tr>
                            <th>Request ID</th>
                            <th>Patient</th>
                            <th>Urgency</th>
                            <th>Status</th>
                            <th>Date</th>
                        </tr>
                    </thead>
                    <tbody>
                        {requests.map((req) => (
                            <tr key={req.RequestID}>
                                <td>{req.RequestID}</td>
                                <td>{req.PatientName}</td>
                                <td>
                                    <span className={`urgency-tag ${req.Urgency.toLowerCase()}`}>
                                        {req.Urgency}
                                    </span>
                                </td>
                                <td>
                                    <span className={`status-tag status-${req.Status.toLowerCase()}`}>
                                        {req.Status.replace(/_/g, ' ')}
                                    </span>
                                </td>
                                <td>{new Date(req.CreatedAt).toLocaleString()}</td>
                            </tr>
                        ))}
                    </tbody>
                </table>
            )}
        </div>
    );
};

export default RequestStatusDashboard;
